      SUBROUTINE HARDENCC     COORDINATE TRANSFORMATIONS FOR MISALIGNMENTS OF BEAM SECTIONSC     (TO BE STORED WITH ALIGN ELEMENT)CC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM0F.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM9.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM23.CIN'      INCLUDE 'ELM24A.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'OCP.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'R2P.CIN'CC     LOCAL VARIABLESC      INTEGER         IADR, IDATA, IRI, J, K, NMUP, NSLIT      REAL            DATAR      EXTERNAL        DATAR, IDATAC-----------------------------------------------------------------------CC     RESET MATRICESC      NUM = 1      NDIF = 1      LPRF = .FALSE.      ATWORK = NUSE .EQ. 0      MKG = .FALSE.      CALL UNITS(0)      CALL RESET(2)      CALL RESET(3)      CALL RESET(4)CC     BRANCH ON ELEMENT TYPEC    1 I = ISTOR(NUM)      TYPE = IDATA(I)      TYPEC = TYPE      IF (TYPE .LE. 0 .OR. TYPE .GE. 50) GO TO 5010      CALL SKETCH(NUM)      CALL DEPICT      CALL DEPIC2      IF (.NOT. ATWE) GO TO 5010      IF (DOPARS .AND. TYPE .NE. 23 .AND. TYPE .NE. 30 .AND.     1    TYPE .NE. 9 .AND. TYPE .NE. 24 .AND. TYPE .NE. 31) GO TO 5010      IF (TYPE .EQ. 1) GO TO 100      IF (TYPE .EQ. 3) GO TO 300      IF (TYPE .EQ. 4) GO TO 400      IF (TYPE .EQ. 5) GO TO 500      IF (TYPE .EQ. 6) GO TO 600      IF (TYPE .EQ. 8) GO TO 800      IF (TYPE .EQ. 9) GO TO 900      IF (TYPE .EQ. 11) GO TO 1100      IF (TYPE .EQ. 13) THEN        CDB = INT(DATA(I+1))        IF (CDB .EQ. 9) GO TO 1300      ENDIF      IF (TYPE .EQ. 15) GO TO 1500      IF (TYPE .EQ. 18) GO TO 1800      IF (TYPE .EQ. 19) GO TO 1900      IF (TYPE .EQ. 20) GO TO 2000      IF (TYPE .EQ. 23) GO TO 2300      IF (TYPE .EQ. 24) GO TO 2400      IF (TYPE .EQ. 25) GO TO 2500      IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) GO TO 2800      IF (TYPE .EQ. 31) GO TO 3100      IF (TYPE .EQ. 34) GO TO 3400      IF (TYPE .EQ. 35 .OR. TYPE .EQ. 36) GO TO 3500      IF (TYPE .EQ. 37) GO TO 3700      IF (TYPE .EQ. 43) THEN        IF (.NOT. (ALIGN .OR. LAY)) GO TO 5010        IF (.NOT. (RCP .OR. R2P)) GO TO 5010        GO TO 4300      ENDIF      GO TO 5010CC     1. -- BEAMC  100 IRI = IPTOJ(7)      IF (IRI .NE. 0) THEN        RI = DATA(I + IRI)*UNITI(11)        IF (.NOT. LPRF) PREF = RI      ENDIF      GO TO 5000CC     3. -- DRIFT SPACEC  300 IADR = I + 1      L = DATAR(IADR)*UNITI(8)      GO TO 5000CC     4. -- BENDING MAGNETC  400 CALL BGET(I)      L = LBEND      GO TO 5000CC     5. -- QUADRUPOLEC  500 L = DATAR(I+1)*UNITI(8)      GO TO 5000CC     6. -- UPDATEC  600 NSLIT = INT(DATA(I+1))      IF (NSLIT .NE. 0) GO TO 5000      NMUP = INT(DATA(I+2))      IF (NMUP .EQ. 1) THEN        RCP = .FALSE.        R2P = .FALSE.        OCP(2) = .FALSE.      ENDIF      IF (NMUP .EQ. 2) THEN        RCP = RCP .OR. R2P        R2P = .FALSE.        OCP(3) = .FALSE.      ENDIF      GO TO 5010CC     8. -- STORE COORDINATE TRANSFORMATION IN MISALIGNMENT ELEMENTC  800 TYT = INT(DATA(I+7))      RORC = MOD(TYT,10)      IR = RORC + 1      IF (RORC .GE. 3) GO TO 5010      I = I + 9      DO 810 J = 1, 3      DATA(I+J) = X0(IR,J)  810 CONTINUEC      I = I + 3      DO 820 J = 1, 3      DO 820 K = 1, 3      I = I + 1      DATA(I) = O(IR,J,K)  820 CONTINUE            GO TO 5010CC     9. -- REPEATC  900 NREP = IDATA(I+1)      CALL REPEAT1      IF (FLUSHL) GO TO 5100      GO TO 5010CC     11. -- ACCELERATORC 1100 L = DATAR(I+1)*UNITI(8)      GO TO 5000CC     13. -- REALIGNMENT OF BEAM LINEC 1300 GO TO 5000CC     15. -- UNITSC 1500 J = INT(DATA(I+1))      IF (J .EQ. 20) GO TO 1510      XNAME = LABEL(NUM)(1:4)      USIZE = DATA(I+2)      CALL UNITS(J)      GO TO 5000C 1510 MPMAD = .TRUE.      GO TO 5000CC     18. -- SEXTUPOLEC 1800 L = DATAR(I+1)*UNITI(8)      GO TO 5000CC     19. -- SOLENOIDC 1900 L = DATAR(I+1)*UNITI(8)      GO TO 5000CC     20. -- COORDINATE ROTATIONC 2000 GO TO 5000CC     23. -- ALGEBRAIC OPERATIONC 2300 K1REG = IDATA(I+1)      K1TIE = TIE(I+1)      K2REG = IDATA(I+2)      K2TIE = TIE(I+2)      IOPN = IDATA(I+3)      JREG = IDATA(I+4)      JTIE = TIE(I+4)      CALL COMBIN      GO TO 5010CC     24. -- DEFINE SECTIONC 2400 JDEF = IDATA(I+1)      IF (JDEF .EQ. 3 .OR. JDEF .EQ. 4) THEN        NADDEF(1) = IDATA(I+2)        NADDEF(2) = IDATA(I+3)      ENDIF      CALL DEFINE      IF (FLUSHL) GO TO 5100      GO TO 5010CC     25. -- OCTUPOLEC 2500 L = DATAR(I+1)*UNITI(8)      GO TO 5000CC     28. -- RBEND OR 29. -- SBENDC 2800 TYPEC = 4      CALL RBGET      L = DATAR(I+1)*UNITI(8)      GO TO 5000CC     31. -- POSITION MARKERC 3100 NMARKS = IDATA(I+1)      DRC = .FALSE.      CALL AGENDA(1)      GO TO 5010CC     34. -- PLASMA LENSC 3400 L = DATAR(I+1)*UNITI(8)      GO TO 5000CC     35. -- HKICK OR 36. -- VKICKC 3500 L = DATAR(I+1)*UNITI(8)      GO TO 5000CC     37. -- ALIGNMENT MARKERC 3700 NSLIT = INT(DATA(I+1))      IF (NSLIT .NE. 0) GO TO 5000      NMUP = INT(DATA(I+2))      IF (NMUP .EQ. 1) OCP(2) = .FALSE.      IF (NMUP .EQ. 2) OCP(3) = .FALSE.      GO TO 5010CC     43. -- COORDINATE SYSTEM SHIFTC 4300 GO TO 5000CC     COORDINATE ADVANCES FOR INDIVIDUAL ELEMENTSC 5000 CALL OSET      CALL ADVANC(2)      CALL ADVANC(3)      R2P = .TRUE.      IF (NMISRB .NE. 0) CALL AGENDR(1)CC     ADVANCE TO NEXT ELEMENTC 5010 IF (MKG .AND. NUM .EQ. NMARKE) CALL AGENDA(2)      IF (ALGR .AND. NUM .EQ. NMISRE) CALL AGENDR(2)      NUM = NUM + NDIF      IF (.NOT. MKG .AND. NUSE .NE. 0 .AND. NUM .GT. NUSE) GO TO 5100      IF (NUM .LE. NEL) GO TO 1 5100 RETURN      END